package com.pringlestars.livesubtitle;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.Settings;import android.media.projection.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences p; Preview preview;
 String[] keys={"x","y","w","h","size","interval"}; int[] defaults={5,60,90,15,20,500};
 public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},99);p=getSharedPreferences("settings",0); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,48,32,32);ScrollView s=new ScrollView(this);s.addView(l);setContentView(s);
 TextView title=new TextView(this);title.setText("실시간 자막 번역");title.setTextSize(28);l.addView(title);
 button(l,"번역 시작",()->{if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}startActivityForResult(getSystemService(MediaProjectionManager.class).createScreenCaptureIntent(),42);});
 button(l,"번역 중지",()->stopService(new Intent(this,CaptureService.class)));
 preview=new Preview();l.addView(preview,new LinearLayout.LayoutParams(-1,260));
 String[] names={"가로 위치 (%)","세로 위치 (%)","너비 (%)","높이 (%)","글자 크기","인식 주기"};
 for(int i=0;i<6;i++){final int j=i;TextView t=new TextView(this);l.addView(t);SeekBar bar=new SeekBar(this);bar.setMax(i==5?3:i==4?40:100);int v=p.getInt(keys[i],defaults[i]);int[] intervals={300,500,1000,2000};bar.setProgress(i==5?(v==300?0:v==1000?2:v==2000?3:1):v);t.setText(names[i]+": "+v);l.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean u){int a=j==5?intervals[n]:j==4?Math.max(12,n):n;p.edit().putInt(keys[j],a).apply();t.setText(names[j]+": "+a);preview.invalidate();}});}
 button(l,"진단 상태 확인",()->new AlertDialog.Builder(this).setTitle("최근 번역 상태").setMessage(p.getString("diagnostic","아직 캡처 기록 없음")).setPositiveButton("확인",null).show());TextView info=new TextView(this);info.setText("영어 → 한국어 · 최초 모델 다운로드에 인터넷 필요\n전체 화면 공유를 선택하세요. 영역 변경 후 번역을 다시 시작하세요.");l.addView(info);}
 void button(LinearLayout l,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setOnClickListener(v->r.run());l.addView(b);}
 protected void onActivityResult(int q,int c,Intent d){super.onActivityResult(q,c,d);if(q==42&&c==RESULT_OK&&d!=null){Intent i=new Intent(this,CaptureService.class);i.putExtra("code",c);i.putExtra("data",d);startForegroundService(i);moveTaskToBack(true);}}
 class Preview extends View{Paint a=new Paint();Preview(){super(MainActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();a.setColor(0xff202b39);c.drawRect(0,0,w,h,a);a.setColor(0xff43d9ac);a.setStyle(Paint.Style.STROKE);a.setStrokeWidth(4);float x=w*p.getInt("x",5)/100,y=h*p.getInt("y",60)/100;c.drawRect(x,y,Math.min(w,x+w*p.getInt("w",90)/100),Math.min(h,y+h*p.getInt("h",15)/100),a);a.setStyle(Paint.Style.FILL);}}
}